from abc import ABC, abstractmethod

# Abstract class for sorting algorithms
class SortAlgorithm(ABC):
    def __init__(self):
        pass

    # Template method for sorting
    @abstractmethod
    def sort(self, array):
        pass

    # Abstract method for comparing elements
    @abstractmethod
    def compare(self, a, b):
        pass

    # Abstract method for swapping elements
    @abstractmethod
    def swap(self, a, b):
        pass


# Concrete subclass for Bubble Sort
class BubbleSort(SortAlgorithm):
    def sort(self, array):
        n = len(array)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(array[j], array[j + 1]) > 1:
                    self.swap(array[j], array[j + 1])
        return array

    def compare(self, a, b):
        return a - b

    def swap(self, a, b):
        a, b = b, a
        return a, b


# Concrete subclass for Selection Sort
class SelectionSort(SortAlgorithm):
    def sort(self, array):
        n = len(array)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(array[j], array[min_idx]) < 1:
                    min_idx = j
            self.swap(array[i], array[min_idx])
        return array

    def compare(self, a, b):
        return a - b

    def swap(self, a, b):
        a, b = b, a
        return a, b


# Concrete subclass for Merge Sort
class MergeSort(SortAlgorithm):
    def sort(self, array):
        if len(array) <= 1:
            return array
        mid = len(array) // 2
        left_half = self.sort(array[:mid])
        right_half = self.sort(array[mid:])
        return self.merge(left_half, right_half)

    def merge(self, left, right):
        merged = []
        while len(left) > 0 and len(right) > 0:
            if self.compare(left[0], right[0]) <= 0:
                merged.append(left.pop(0))
            else:
                merged.append(right.pop(0))
        merged.extend(left)
        merged.extend(right)
        return merged

    def compare(self, a, b):
        return a - b

    def swap(self, a, b):
        a, b = b, a
        return a, b


